'use client';

import { Species, ICONIC_TAXON_EMOJI, IconicTaxon } from '@/lib/types';
import Image from 'next/image';

interface SpeciesCardProps {
  species: Species;
  rank?: number;
  onClick?: () => void;
  isHighlighted?: boolean;
}

export function SpeciesCard({ species, rank, onClick, isHighlighted }: SpeciesCardProps) {
  const emoji = ICONIC_TAXON_EMOJI[species.iconicTaxon as IconicTaxon] || '🔬';

  return (
    <button
      onClick={onClick}
      className={`w-full text-left rounded-xl shadow-sm border transition-all duration-200
                 overflow-hidden group ${
        isHighlighted
          ? 'bg-emerald-50 border-emerald-300 shadow-md ring-2 ring-emerald-200'
          : 'bg-white border-gray-100 hover:shadow-md hover:border-gray-200'
      }`}
    >
      <div className="flex items-center gap-4 p-4">
        {/* Rank badge */}
        {rank && (
          <div className="shrink-0 w-8 h-8 rounded-full bg-emerald-50
                          flex items-center justify-center text-emerald-700
                          font-semibold text-sm">
            {rank}
          </div>
        )}

        {/* Species photo */}
        <div className="shrink-0 w-16 h-16 rounded-lg overflow-hidden bg-gray-100">
          {species.photoUrl ? (
            <Image
              src={species.photoUrl}
              alt={species.commonName}
              width={64}
              height={64}
              className="w-full h-full object-cover group-hover:scale-105 transition-transform"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center text-2xl">
              {emoji}
            </div>
          )}
        </div>

        {/* Species info */}
        <div className="flex-1 min-w-0">
          <h3 className="font-medium text-gray-900 truncate">
            {species.commonName}
          </h3>
          <p className="text-sm text-gray-500 italic truncate">
            {species.name}
          </p>
          <div className="flex items-center gap-2 mt-1">
            <span className="text-xs">{emoji}</span>
            <span className="text-xs text-gray-400">
              {species.observationCount.toLocaleString()} observations
            </span>
          </div>
        </div>

        {/* Arrow indicator */}
        <div className="shrink-0 text-gray-300 group-hover:text-gray-400
                        transition-colors">
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2}
                  d="M9 5l7 7-7 7" />
          </svg>
        </div>
      </div>
    </button>
  );
}
